import { t, type DeepSet } from "../types";

/** Fear and Inner Healing: the Spirit-led teaching for each lesson. */
export const DEEP: DeepSet = {
  "c-fear-of-man": {
    revelation: t(
      "Whoever you fear the most will end up ruling your life, so God invites you to fear Him alone and be free from everyone else.",
      "Kung sino ang pinakakinatatakutan mo, siya ang maghahari sa buhay mo; kaya inaanyayahan ka ng Diyos na Siya lang ang katakutan mo at lumaya ka sa lahat ng iba."
    ),
    mainTruth: t(
      "\"The fear of man lays a snare, but whoever trusts in the Lord is safe\" (Proverbs 29:25). Saul lost his kingdom because he \"feared the people and obeyed their voice\" (1 Samuel 15:24). Some leaders believed in Jesus but kept quiet, \"for they loved the glory that comes from man more than the glory that comes from God\" (John 12:42-43). Jesus gives the cure: do not fear those who can only kill the body; fear God, who counts every hair on your head and values you more than many sparrows (Matthew 10:28-31). When you fear God rightly, you can say with Peter and John, \"We cannot but speak\" (Acts 4:20).",
      "\"Ang takot sa tao ay isang bitag, ngunit ang nagtitiwala sa Panginoon ay ligtas\" (Kawikaan 29:25). Nawala kay Saul ang kaharian dahil \"natakot siya sa mga tao at sinunod ang kanilang tinig\" (1 Samuel 15:24). May mga pinunong naniwala kay Hesus pero nanahimik, \"sapagkat mas inibig nila ang papuri ng tao kaysa sa papuri ng Diyos\" (Juan 12:42-43). Ibinigay ni Hesus ang lunas: huwag katakutan ang kaya lang pumatay ng katawan; katakutan ang Diyos, na bumibilang ng bawat buhok sa ulo mo at nagpapahalaga sa iyo nang higit sa maraming maya (Mateo 10:28-31). Kapag tama ang takot mo sa Diyos, masasabi mo rin gaya nina Pedro at Juan, \"Hindi namin mapigilang magsalita\" (Gawa 4:20)."
    ),
    insight: [
      t(
        "We usually think fear of man looks like trembling. Often it looks like being \"nice.\" It hides in the yes you did not mean, the joke you laughed at even though it was dirty, the faith you never mention at the office, the gift you cannot afford but give so the relatives will not talk. A snare does not look dangerous; it looks like the normal path until your foot is caught.",
        "Akala natin, ang takot sa tao ay mukhang nanginginig. Madalas, mukha itong \"mabait.\" Nagtatago ito sa \"oo\" na hindi mo naman talaga gusto, sa bastos na biro na tinawanan mo pa rin, sa pananampalatayang hindi mo binabanggit sa opisina, sa regalong hindi mo kaya pero ibinibigay mo para hindi ka pag-usapan ng mga kamag-anak. Ang bitag ay hindi mukhang mapanganib; mukha itong ordinaryong daan hanggang maipit na ang paa mo."
      ),
      t(
        "Notice Saul's excuse: he blamed the people. Fear of man always gives us someone else to blame, and it always costs us something. For Saul it cost a throne. For the leaders in John 12 it cost a public walk with Jesus. The question is not whether you will fear someone; everyone does. The question is who will have the final vote in your life.",
        "Pansinin ang dahilan ni Saul: sinisi niya ang mga tao. Ang takot sa tao ay laging may ibang masisisi, at laging may kapalit. Kay Saul, trono ang naging kapalit. Sa mga pinuno sa Juan 12, ang hayagang paglakad kasama si Hesus. Ang tanong ay hindi kung may katatakutan ka; lahat tayo mayroon. Ang tanong ay kung sino ang may huling boto sa buhay mo."
      ),
    ],
    life: [
      t(
        "Think of Joy, a caregiver in Dubai. Her employer's family asks her to lie to the landlord about who lives in the flat. Her coworkers say, \"Just do it, you will lose your job.\" Her family back home is waiting for the padala. Fear of man whispers that her security is in pleasing her boss. Trust in the Lord says her security is in pleasing God. She politely refuses, ready for the cost. Weeks later the employer quietly tells her, \"That is why we trust you with the children.\" Not every story ends that neatly, but every story where we obey ends with a free heart.",
        "Isipin si Joy, isang caregiver sa Dubai. Pinapagsinungaling siya ng pamilyang pinagtatrabahuhan niya sa landlord tungkol sa kung sino ang nakatira sa flat. Sabi ng mga kasama niya, \"Gawin mo na lang, mawawalan ka ng trabaho.\" Naghihintay ang pamilya niya sa padala. Bulong ng takot sa tao: nasa pagpapasaya sa amo ang seguridad mo. Sabi ng pagtitiwala sa Panginoon: nasa pagpapasaya sa Diyos ang seguridad mo. Magalang siyang tumanggi, handa sa kapalit. Makalipas ang ilang linggo, tahimik na sinabi ng amo, \"Kaya nga ikaw ang pinagkakatiwalaan namin sa mga bata.\" Hindi lahat ng kuwento ay ganito kaganda ang wakas, pero bawat kuwento ng pagsunod ay nagtatapos sa malayang puso."
      ),
      t(
        "In our culture, \"Ano na lang ang sasabihin ng tao?\" can steer whole families. It decides how big the wedding is, which course the child takes, whether we admit a problem or hide it. God is not against honor or respect. But when \"what people will say\" becomes louder than \"what God has said,\" we have handed someone else the steering wheel.",
        "Sa kultura natin, ang \"Ano na lang ang sasabihin ng tao?\" ay kayang magmaneho ng buong pamilya. Ito ang nagdedesisyon kung gaano kalaki ang kasal, anong kurso ang kukunin ng anak, kung aaminin ba ang problema o itatago. Hindi kontra ang Diyos sa paggalang at dangal. Pero kapag mas malakas na ang \"ano ang sasabihin ng tao\" kaysa sa \"ano ang sinabi ng Diyos,\" naibigay na natin sa iba ang manibela."
      ),
    ],
    twist: t(
      "We think the way out of fear is to have no fear at all. Jesus did not say that. He said to fear the right Person. The fear of the Lord is not the terror of a slave; it is the awe of a child who knows his Father is bigger than every threat. A bigger fear swallows the smaller ones. When God becomes huge in your eyes, people shrink back to their true size: not enemies to dread or idols to please, but neighbors to love.",
      "Akala natin, ang paraan para makalaya sa takot ay ang mawalan ng takot. Hindi iyon ang sinabi ni Hesus. Sinabi Niya: katakutan ang tamang Persona. Ang takot sa Panginoon ay hindi sindak ng alipin; ito ang paghanga ng anak na alam na mas malaki ang Ama niya sa anumang banta. Nilalamon ng mas malaking takot ang maliliit. Kapag lumaki ang Diyos sa paningin mo, bumabalik ang mga tao sa tunay nilang laki: hindi kaaway na kinatatakutan o diyus-diyosang pinasasaya, kundi kapwang mamahalin."
    ),
    confirm: [
      t("Galatians 1:10: if Paul were still pleasing people, he would not be a servant of Christ.", "Galacia 1:10: kung nagpapasaya pa si Pablo ng tao, hindi siya magiging lingkod ni Cristo."),
      t("Daniel 3:16-18: three young men stood before a king and said, \"Even if He does not deliver us, we will not bow.\"", "Daniel 3:16-18: tatlong binata ang tumayo sa harap ng hari at nagsabi, \"Kahit hindi Niya kami iligtas, hindi kami yuyuko.\""),
      t("Matthew 26:69-75: Peter denied Jesus before a servant girl, yet was restored and later preached boldly.", "Mateo 26:69-75: itinatwa ni Pedro si Hesus sa harap ng isang alilang babae, pero ibinalik siya at kalaunan ay buong tapang na nangaral."),
      t("Psalm 118:6: \"The Lord is on my side; I will not fear. What can man do to me?\"", "Awit 118:6: \"Ang Panginoon ay nasa panig ko; hindi ako matatakot. Ano ang magagawa sa akin ng tao?\""),
    ],
    heart: [
      t(
        "Move from performing for an audience to living before an Audience of One. You will still care about people, but you will no longer need their applause to feel safe.",
        "Lumipat mula sa pagtatanghal para sa mga manonood tungo sa pamumuhay sa harap ng Iisang Manonood. Magmamalasakit ka pa rin sa tao, pero hindi mo na kailangan ang palakpak nila para maramdamang ligtas ka."
      ),
      t(
        "Let your yes be yes and your no be no. Courage grows in small steps: one honest answer, one quiet refusal, one sentence about Jesus at a time.",
        "Hayaang ang oo mo ay oo at ang hindi mo ay hindi. Lumalago ang tapang sa maliliit na hakbang: isang tapat na sagot, isang mahinahong pagtanggi, isang pangungusap tungkol kay Hesus sa bawat pagkakataon."
      ),
    ],
    questions: [
      t("Whose opinion, besides God's, has the strongest pull on your decisions right now?", "Bukod sa Diyos, kaninong opinyon ang pinakamalakas humila sa mga desisyon mo ngayon?"),
      t("Where have you said yes when God wanted you to say no, just to avoid being talked about?", "Saan ka nag-\"oo\" kahit gusto ng Diyos na mag-\"hindi\" ka, para lang hindi ka pag-usapan?"),
      t("Like the leaders in John 12, is there a place where you believe in Jesus but stay silent?", "Gaya ng mga pinuno sa Juan 12, may lugar ba kung saan naniniwala ka kay Hesus pero tahimik ka?"),
      t("What would you do differently this week if only God's approval mattered?", "Ano ang gagawin mong iba ngayong linggo kung ang pagsang-ayon lang ng Diyos ang mahalaga?"),
    ],
    actions: [
      t("Write down one decision you have been making to please people, and ask God what He wants you to do instead.", "Isulat ang isang desisyong ginagawa mo para pasayahin ang tao, at tanungin ang Diyos kung ano ang gusto Niyang gawin mo."),
      t("Say one honest, kind \"no\" this week where you would normally give a fearful \"yes.\"", "Magsabi ng isang tapat at mabait na \"hindi\" ngayong linggo kung saan karaniwan kang nagbibigay ng takot na \"oo.\""),
      t("Memorize Proverbs 29:25 and pray it each time you feel the pull to please people.", "Isaulo ang Kawikaan 29:25 at ipanalangin ito tuwing nararamdaman mo ang hila na pasayahin ang tao."),
    ],
    prayer: t(
      "Father, I confess that I have often feared people more than I have feared You. I have wanted their approval, their applause and their silence more than Your smile. Forgive me. Be bigger in my eyes than any boss, relative or crowd. Thank You that You count every hair on my head and call me valuable. Fill me with holy courage, so that I can speak, obey and love freely before You alone. In Jesus' name, Amen.",
      "Ama, inaamin ko na madalas mas natakot ako sa tao kaysa sa Iyo. Mas hinangad ko ang pagsang-ayon nila, ang palakpak nila at ang pananahimik nila kaysa sa ngiti Mo. Patawarin Mo ako. Lumaki Ka sa paningin ko nang higit sa sinumang amo, kamag-anak o madla. Salamat dahil binibilang Mo ang bawat buhok sa ulo ko at itinuturing Mo akong mahalaga. Punuin Mo ako ng banal na tapang, para malaya akong makapagsalita, makasunod at makapagmahal sa harap Mo lamang. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-fear-of-failure": {
    revelation: t(
      "God is not afraid of your failure; He is grieved only when fear makes you bury what He gave you.",
      "Hindi takot ang Diyos sa pagkabigo mo; ang ikinalulungkot Niya ay kapag dahil sa takot ay ibinaon mo ang ibinigay Niya sa iyo."
    ),
    mainTruth: t(
      "In the parable of the talents, the servant who failed was not the one who tried and lost; it was the one who said, \"I was afraid, and I went and hid your talent in the ground\" (Matthew 25:25). God answered Moses' excuse, \"I am slow of speech,\" with \"Who has made man's mouth? Now go, and I will be with your mouth\" (Exodus 4:10-12). Peter, who failed Jesus three times, was restored three times and told, \"Feed My sheep\" (John 21:15-17). Paul learned that God's power \"is made perfect in weakness\" (2 Corinthians 12:9). The righteous fall seven times and rise again (Proverbs 24:16). Failure is not final for those who belong to Christ.",
      "Sa talinghaga ng mga talento, ang aliping nabigo ay hindi ang sumubok at nalugi; ito ang nagsabing, \"Natakot ako, kaya ibinaon ko sa lupa ang talento mo\" (Mateo 25:25). Sinagot ng Diyos ang dahilan ni Moises na \"mabagal akong magsalita\" ng, \"Sino ang gumawa ng bibig ng tao? Humayo ka, at Ako ang sasama sa bibig mo\" (Exodo 4:10-12). Si Pedro, na tatlong beses nabigo kay Hesus, ay tatlong beses ding ibinalik at sinabihan, \"Pakainin mo ang Aking mga tupa\" (Juan 21:15-17). Natutunan ni Pablo na ang kapangyarihan ng Diyos ay \"nagiging ganap sa kahinaan\" (2 Corinto 12:9). Ang matuwid ay pitong ulit mabuwal at muling babangon (Kawikaan 24:16). Hindi katapusan ang pagkabigo sa mga nakay Cristo."
    ),
    insight: [
      t(
        "Look closely at the third servant. His problem was not lack of ability; he had a talent. His problem was a wrong picture of his master: \"I knew you to be a hard man.\" Fear of failure is often a theology problem before it is a confidence problem. If you see God as a harsh boss waiting to catch your mistakes, you will play safe and bury your gifts. If you see Him as a generous Father who entrusted you with something, you will dare to invest it.",
        "Tingnan nang mabuti ang ikatlong alipin. Hindi kakulangan sa kakayahan ang problema niya; may talento siya. Ang problema niya ay maling larawan ng kanyang amo: \"Alam kong mabagsik kang tao.\" Ang takot sa pagkabigo ay madalas problema muna sa pagkakilala sa Diyos bago maging problema sa kumpiyansa. Kung ang tingin mo sa Diyos ay malupit na amo na naghihintay mahuli ang pagkakamali mo, maglalaro ka nang ligtas at ibabaon mo ang kaloob mo. Kung nakikita mo Siya bilang mapagbigay na Ama na nagtiwala sa iyo, maglalakas-loob kang ipuhunan ito."
      ),
      t(
        "Many believers have quietly retired from serving God because of one past failure: a ministry that collapsed, a business that went bankrupt, a marriage that broke, a relapse into an old sin. Jesus did not ask Peter, \"Will you promise never to fail again?\" He asked, \"Do you love Me?\" Restoration starts with love, not with a perfect record.",
        "Maraming mananampalataya ang tahimik nang nagretiro sa paglilingkod sa Diyos dahil sa isang nakaraang pagkabigo: ministeryong bumagsak, negosyong nalugi, pagsasamang nasira, pagbabalik sa lumang kasalanan. Hindi tinanong ni Hesus si Pedro, \"Mangangako ka bang hindi ka na mabibigo?\" Ang tanong Niya ay, \"Mahal mo ba Ako?\" Nagsisimula ang pagbabalik sa pag-ibig, hindi sa perpektong rekord."
      ),
    ],
    life: [
      t(
        "Mark worked as a seafarer for years, saved hard, and opened a small carinderia in his province. Within a year it closed. Relatives whispered. He felt foolish and swore never to try anything again. Even when his church asked him to lead the men's group, he said, \"Hindi ako para diyan, palpak ako.\" One night he read John 21 and saw that Jesus served breakfast to the man who had failed Him. Mark realized that his failed carinderia had taught him about people, money and humility. Today he leads that men's group, and his first story is always his failure.",
        "Ilang taon nagtrabaho si Mark bilang seaman, nag-ipon nang husto, at nagbukas ng maliit na karinderya sa probinsya. Wala pang isang taon, nagsara ito. Nagbulungan ang mga kamag-anak. Nahiya siya at nangakong hindi na susubok ng kahit ano. Kahit inalok siya ng simbahan na pangunahan ang grupo ng kalalakihan, sabi niya, \"Hindi ako para diyan, palpak ako.\" Isang gabi, nabasa niya ang Juan 21 at nakita na si Hesus mismo ang naghain ng almusal sa taong nabigo sa Kanya. Napagtanto ni Mark na ang nalugi niyang karinderya ang nagturo sa kanya tungkol sa tao, pera at kababaang-loob. Ngayon, siya na ang namumuno sa grupong iyon, at ang una niyang kuwento ay laging ang pagkabigo niya."
      ),
      t(
        "Students fear failing the board exam, workers fear failing the visa interview, parents fear failing their children. These are real fears. But a failed exam is an event, not an identity. God does not file you under \"failure\"; He files you under \"My child.\" From that place you can try again, learn again and serve again.",
        "Takot ang estudyante na bumagsak sa board exam, ang manggagawa sa visa interview, ang magulang na mabigo sa mga anak. Totoo ang mga takot na ito. Pero ang bagsak na exam ay pangyayari, hindi pagkakakilanlan. Hindi ka inilalagay ng Diyos sa folder na \"palpak\"; inilalagay ka Niya sa folder na \"Aking anak.\" Mula roon, kaya mong sumubok muli, matuto muli at maglingkod muli."
      ),
    ],
    twist: t(
      "We think God uses us in spite of our weakness. Paul discovered something deeper: God uses us through our weakness. \"I will boast all the more gladly of my weaknesses, so that the power of Christ may rest upon me\" (2 Corinthians 12:9). Your limp, your history and your \"I am not good at this\" may be the very doorway through which people see that the strength is God's, not yours. In the Kingdom, the cracked jar is the one that lets the light out.",
      "Akala natin, ginagamit tayo ng Diyos sa kabila ng ating kahinaan. Mas malalim ang natuklasan ni Pablo: ginagamit tayo ng Diyos sa pamamagitan ng ating kahinaan. \"Lalo kong ipagmamalaki ang aking mga kahinaan, upang manahan sa akin ang kapangyarihan ni Cristo\" (2 Corinto 12:9). Ang pagkapilay mo, ang nakaraan mo at ang \"hindi ako magaling dito\" mo ay maaaring siyang pinto para makita ng tao na sa Diyos ang lakas, hindi sa iyo. Sa Kaharian, ang basag na banga ang nagpapalabas ng liwanag."
    ),
    confirm: [
      t("Philippians 3:13-14: Paul forgets what lies behind and presses on toward the prize.", "Filipos 3:13-14: kinakalimutan ni Pablo ang nasa likuran at nagpapatuloy patungo sa gantimpala."),
      t("Judges 6:15-16: Gideon, the least in his family, hears \"I will be with you.\"", "Hukom 6:15-16: si Gideon, ang pinakamaliit sa pamilya, ay nakarinig ng \"Ako ay sasaiyo.\""),
      t("Micah 7:8: \"When I fall, I shall rise; when I sit in darkness, the Lord will be a light to me.\"", "Mikas 7:8: \"Kapag ako'y nabuwal, ako'y babangon; kapag ako'y nasa dilim, ang Panginoon ang ilaw ko.\""),
      t("Acts 15:37-39 and 2 Timothy 4:11: John Mark quit once, yet later Paul called him useful for ministry.", "Gawa 15:37-39 at 2 Timoteo 4:11: minsang umatras si Juan Marcos, pero kalaunan tinawag siya ni Pablo na kapaki-pakinabang sa ministeryo."),
    ],
    heart: [
      t(
        "Trade perfectionism for faithfulness. God says \"well done, good and faithful servant,\" not \"well done, flawless servant.\"",
        "Ipagpalit ang pagiging perpeksiyonista sa pagiging tapat. Ang sinasabi ng Diyos ay \"magaling, mabuti at tapat na alipin,\" hindi \"magaling, walang-kapintasang alipin.\""
      ),
      t(
        "Be gentle with yourself and with others who fail. The way you treat a failing brother shows what you really believe about grace.",
        "Maging mahinahon sa sarili at sa ibang nabibigo. Ang pagtrato mo sa kapatid na nabigo ang nagpapakita kung ano talaga ang paniniwala mo tungkol sa biyaya."
      ),
    ],
    questions: [
      t("What gift, dream or calling have you buried because you were afraid to fail?", "Anong kaloob, pangarap o tawag ang ibinaon mo dahil natakot kang mabigo?"),
      t("Is your picture of God closer to \"a hard man\" or to the Father who restored Peter?", "Ang larawan mo ba ng Diyos ay mas malapit sa \"mabagsik na tao\" o sa Amang nagbalik kay Pedro?"),
      t("Which past failure still speaks louder in your mind than God's word about you?", "Aling nakaraang pagkabigo ang mas malakas pa ring nagsasalita sa isip mo kaysa sa salita ng Diyos tungkol sa iyo?"),
      t("How could God use your weakness to show His strength to someone else?", "Paano magagamit ng Diyos ang kahinaan mo para maipakita ang lakas Niya sa iba?"),
    ],
    actions: [
      t("Name one buried \"talent\" and take one small step to use it this week: sign up, offer, start.", "Pangalanan ang isang ibinaong \"talento\" at gumawa ng isang maliit na hakbang para gamitin ito ngayong linggo: magpalista, mag-alok, magsimula."),
      t("Write your biggest failure on paper, then write over it: \"Do you love Me? Feed My sheep.\"", "Isulat sa papel ang pinakamalaki mong pagkabigo, at isulat sa ibabaw nito: \"Mahal mo ba Ako? Pakainin mo ang Aking mga tupa.\""),
      t("Share one failure and what God taught you through it with a friend or your small group.", "Ibahagi sa isang kaibigan o sa small group ang isang pagkabigo at kung ano ang itinuro ng Diyos sa iyo roon."),
    ],
    prayer: t(
      "Lord, You know every place I have fallen. Some of my failures still shame me, and some have made me afraid to try again. Thank You that You restored Peter and that You are not finished with me. Heal my picture of You. I give You my weakness; let Your power rest on me. Help me dig up what I have buried and invest it for Your glory, not for my image. In Jesus' name, Amen.",
      "Panginoon, alam Mo ang bawat lugar kung saan ako nabuwal. May mga pagkabigo ko na nakakahiya pa rin, at may mga nagpatakot sa akin na sumubok muli. Salamat dahil ibinalik Mo si Pedro at hindi Ka pa tapos sa akin. Pagalingin Mo ang larawan ko tungkol sa Iyo. Ibinibigay ko sa Iyo ang aking kahinaan; manahan nawa sa akin ang kapangyarihan Mo. Tulungan Mo akong hukayin ang ibinaon ko at ipuhunan ito para sa Iyong kaluwalhatian, hindi para sa aking imahe. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-fear-of-rejection": {
    revelation: t(
      "Before anyone could reject you, God had already chosen you, and in Christ that choice will never be taken back.",
      "Bago ka pa matanggihan ng sinuman, pinili ka na ng Diyos, at kay Cristo, hindi na kailanman babawiin ang pagpiling iyon."
    ),
    mainTruth: t(
      "\"He chose us in Him before the foundation of the world... He predestined us for adoption as sons through Jesus Christ... to the praise of His glorious grace, with which He has blessed us in the Beloved\" (Ephesians 1:4-6). Jesus promised, \"Whoever comes to Me I will never cast out\" (John 6:37). Even if father and mother forsake us, \"the Lord will take me in\" (Psalm 27:10). Jesus Himself was \"despised and rejected by men\" (Isaiah 53:3), so He knows the pain from the inside. Because Christ has welcomed us, we are called to welcome one another (Romans 15:7).",
      "\"Pinili Niya tayo kay Cristo bago pa itatag ang sanlibutan... itinalaga Niya tayo upang maging Kanyang mga anak sa pamamagitan ni Hesu-Cristo... para sa kapurihan ng Kanyang maluwalhating biyaya na ibinigay Niya sa atin sa Kanyang Minamahal\" (Efeso 1:4-6). Nangako si Hesus, \"Ang lumapit sa Akin ay hinding-hindi Ko itataboy\" (Juan 6:37). Kahit pabayaan tayo ng ama at ina, \"ang Panginoon ang kukupkop sa akin\" (Awit 27:10). Si Hesus mismo ay \"hinamak at itinakuwil ng mga tao\" (Isaias 53:3), kaya alam Niya ang sakit mula sa loob. Dahil tinanggap tayo ni Cristo, tinatawag tayong tanggapin ang isa't isa (Roma 15:7)."
    ),
    insight: [
      t(
        "Leah's story in Genesis 29 is one of the most honest in the Bible. Unloved by Jacob, she named her sons hoping, \"Now my husband will love me.\" Again and again she waited for a human heart to finally accept her. Then with Judah she said something new: \"This time I will praise the Lord.\" Nothing in Jacob had changed; something in Leah had. And from Judah came King David and, later, Jesus. God was writing redemption through the woman who felt rejected.",
        "Isa sa pinakatapat na kuwento sa Bibliya ang kay Lea sa Genesis 29. Hindi siya mahal ni Jacob, kaya pinangalanan niya ang mga anak niya nang may pag-asang, \"Ngayon, mamahalin na ako ng asawa ko.\" Paulit-ulit siyang naghintay na sa wakas ay tanggapin siya ng isang pusong tao. Pagkatapos, kay Juda, may bago siyang sinabi: \"Ngayon, pupurihin ko ang Panginoon.\" Walang nagbago kay Jacob; may nagbago kay Lea. At mula kay Juda nagmula si Haring David at, kalaunan, si Hesus. Isinusulat ng Diyos ang pagtubos sa pamamagitan ng babaeng pakiramdam ay tinanggihan."
      ),
      t(
        "Fear of rejection makes us build walls or wear masks. Some people reject others first so they will not be hurt. Others become people-pleasers who never show their real selves. Both are trying to answer a question that only God can answer: \"Am I wanted?\" When we demand that answer from a spouse, a parent or a group of friends, we place on them a weight that only Christ can carry.",
        "Ang takot sa pagtanggi ay nagpapagawa sa atin ng pader o nagpapasuot ng maskara. May mga taong nauunang tumanggi sa iba para hindi sila masaktan. Ang iba naman ay nagiging people-pleaser na hindi na naipapakita ang tunay na sarili. Pareho silang sumusubok sumagot sa tanong na Diyos lang ang makasasagot: \"May nagnanais ba sa akin?\" Kapag hinihingi natin ang sagot na iyon sa asawa, magulang o barkada, ipinapasan natin sa kanila ang bigat na si Cristo lang ang kayang magpasan."
      ),
    ],
    life: [
      t(
        "Ana grew up as the \"extra\" child. Her parents left her with her lola while they worked abroad, and when they came back, her younger siblings seemed to get all the attention. As an adult she became the one who never refused anything at work or church, terrified that if she disappointed people, she would be left out again. In a women's Bible study she heard Psalm 27:10 read aloud: \"Though my father and mother forsake me, the Lord will take me in.\" She cried for the first time in years. Healing did not happen in one night, but she started to rest in being chosen, and slowly learned that she could say no and still be loved.",
        "Lumaki si Ana bilang \"sobrang\" anak. Iniwan siya ng mga magulang niya sa lola habang nagtatrabaho sila sa abroad, at nang umuwi sila, parang sa mga nakababatang kapatid napunta ang lahat ng atensyon. Paglaki niya, siya ang hindi kailanman tumatanggi sa trabaho o sa simbahan, takot na takot na kapag nabigo niya ang tao, maiiwan na naman siya. Sa isang Bible study ng kababaihan, narinig niyang binasa nang malakas ang Awit 27:10: \"Kahit pabayaan ako ng ama at ina ko, ang Panginoon ang kukupkop sa akin.\" Umiyak siya sa unang pagkakataon sa loob ng maraming taon. Hindi nangyari ang paggaling sa isang gabi, pero nagsimula siyang magpahinga sa katotohanang pinili siya, at unti-unting natutunan na puwede siyang tumanggi at mahal pa rin."
      ),
      t(
        "OFWs know a special kind of rejection: the job application that never gets a reply, the employer who treats you as invisible, the family who only calls when they need money. In those moments, remember that the God of heaven does not see you as a worker number. He sees a son, a daughter, someone He sang over before you were born.",
        "May natatanging uri ng pagtanggi na kilala ng mga OFW: ang application na hindi na sinagot, ang amo na parang hindi ka nakikita, ang pamilyang tumatawag lang kapag kailangan ng pera. Sa mga sandaling iyon, alalahanin na hindi ka tinitingnan ng Diyos ng langit bilang numero ng manggagawa. Ang nakikita Niya ay anak na lalaki o babae, isang taong inawitan na Niya bago ka pa isinilang."
      ),
    ],
    twist: t(
      "The cross shows something astonishing: Jesus was rejected so that you could be accepted. On the cross He cried, \"My God, My God, why have You forsaken Me?\" (Matthew 27:46). He tasted the deepest rejection any person could ever feel, being cut off from the Father, so that you would never have to. Your worst fear has already been carried by Someone else. Because He was cast out, you will never be cast out.",
      "Ipinapakita ng krus ang isang kamangha-manghang bagay: tinanggihan si Hesus para ikaw ay matanggap. Sa krus, sumigaw Siya, \"Diyos Ko, Diyos Ko, bakit Mo Ako pinabayaan?\" (Mateo 27:46). Natikman Niya ang pinakamalalim na pagtanggi na mararamdaman ng tao, ang mahiwalay sa Ama, para hindi mo na ito danasin kailanman. Ang pinakamalaki mong takot ay napasan na ng Iba. Dahil itinaboy Siya, hindi ka na kailanman itataboy."
    ),
    confirm: [
      t("Luke 15:20: the father ran to the returning son before he could finish his speech.", "Lucas 15:20: tumakbo ang ama sa pabalik na anak bago pa nito matapos ang kanyang talumpati."),
      t("John 4:7-26: Jesus sought out a Samaritan woman whom others avoided.", "Juan 4:7-26: hinanap ni Hesus ang babaeng Samaritana na iniiwasan ng iba."),
      t("2 Samuel 9:7: David invited lame Mephibosheth to eat at the king's table always.", "2 Samuel 9:7: inanyayahan ni David ang pilay na si Mephiboset na laging kumain sa hapag ng hari."),
      t("1 Peter 2:4: Jesus is the living stone rejected by men but chosen and precious to God.", "1 Pedro 2:4: si Hesus ang buhay na batong itinakuwil ng tao pero pinili at mahalaga sa Diyos."),
    ],
    heart: [
      t(
        "Start your day from acceptance, not for acceptance. You do not serve, work or love to earn a place; you already have one.",
        "Simulan ang araw mula sa pagtanggap, hindi para sa pagtanggap. Hindi ka naglilingkod, nagtatrabaho o nagmamahal para makakuha ng puwesto; mayroon ka na."
      ),
      t(
        "Become a welcomer. People who know they are chosen notice the lonely person at church and the new worker at the site.",
        "Maging mapagtanggap. Ang mga taong alam na pinili sila ay napapansin ang nag-iisang tao sa simbahan at ang bagong manggagawa sa site."
      ),
    ],
    questions: [
      t("Whose rejection, past or present, still shapes how you see yourself?", "Kaninong pagtanggi, noon o ngayon, ang humuhubog pa rin sa tingin mo sa sarili?"),
      t("Do you tend to build walls or wear masks when you fear being rejected?", "Ikaw ba ay nagtatayo ng pader o nagsusuot ng maskara kapag natatakot kang tanggihan?"),
      t("Like Leah, whose love are you still waiting for before you can praise God?", "Gaya ni Lea, kaninong pagmamahal ang hinihintay mo pa bago ka makapagpuri sa Diyos?"),
      t("Who around you needs to feel welcomed the way Christ welcomed you?", "Sino sa paligid mo ang kailangang maramdamang tanggap siya, gaya ng pagtanggap sa iyo ni Cristo?"),
    ],
    actions: [
      t("Read Ephesians 1:3-6 aloud each morning this week, putting your name in it.", "Basahin nang malakas ang Efeso 1:3-6 tuwing umaga ngayong linggo, at ilagay ang pangalan mo rito."),
      t("Bring one specific memory of rejection to God in prayer and ask Him to show you where He was.", "Dalhin sa panalangin ang isang tiyak na alaala ng pagtanggi at hilingin sa Diyos na ipakita kung nasaan Siya noon."),
      t("Reach out this week to someone who seems left out: a new member, a lonely coworker, a forgotten relative.", "Lapitan ngayong linggo ang isang taong mukhang naiiwan: bagong miyembro, nag-iisang katrabaho, nakalimutang kamag-anak."),
    ],
    prayer: t(
      "Father, thank You that You chose me before the world began and that in Jesus I am accepted. You know the faces and the words that have wounded me. I bring them to You. Heal the places where rejection still lives in me. Help me stop begging people for what You have already given. Jesus, You were rejected so I could be welcomed; make me a welcomer like You. In Your name, Amen.",
      "Ama, salamat dahil pinili Mo ako bago pa nilikha ang mundo at kay Hesus ay tanggap ako. Alam Mo ang mga mukha at salitang sumugat sa akin. Dinadala ko ang mga ito sa Iyo. Pagalingin Mo ang mga bahagi ng puso ko kung saan buhay pa ang pagtanggi. Tulungan Mo akong tumigil sa pagmamakaawa sa tao para sa ibinigay Mo na. Hesus, tinanggihan Ka para ako ay matanggap; gawin Mo akong mapagtanggap gaya Mo. Sa Iyong pangalan, Amen."
    ),
  },

  "c-fear-of-future": {
    revelation: t(
      "You do not know what tomorrow holds, but you can know who holds your tomorrow, and that is enough to sleep tonight.",
      "Hindi mo alam kung ano ang mangyayari bukas, pero kilala mo kung Sino ang may hawak ng bukas mo, at sapat na iyon para makatulog ka ngayong gabi."
    ),
    mainTruth: t(
      "God told exiles in Babylon, a people whose future looked ruined, \"I know the plans I have for you... plans for welfare and not for evil, to give you a future and a hope\" (Jeremiah 29:11). That promise came with a seventy-year wait (29:10) and a call to seek Him with all their heart (29:13). Jesus says, \"Do not be anxious about tomorrow\" (Matthew 6:34). James reminds us that we should say, \"If the Lord wills, we will live and do this or that\" (James 4:15). We plan, but the Lord directs our steps (Proverbs 16:9). With David we can pray, \"My times are in Your hand\" (Psalm 31:15), knowing God works all things together for good for those who love Him (Romans 8:28).",
      "Sinabi ng Diyos sa mga bihag sa Babilonia, isang bayang tila wasak na ang kinabukasan, \"Alam Ko ang mga plano Ko para sa inyo... mga planong ikabubuti at hindi ikasasama, upang bigyan kayo ng kinabukasan at pag-asa\" (Jeremias 29:11). May kasamang pitumpung taong paghihintay ang pangakong iyon (t. 10) at panawagang hanapin Siya nang buong puso (t. 13). Sabi ni Hesus, \"Huwag kayong mabalisa tungkol sa bukas\" (Mateo 6:34). Ipinapaalala ni Santiago na dapat nating sabihin, \"Kung loloobin ng Panginoon, mabubuhay kami at gagawin namin ito o iyon\" (Santiago 4:15). Nagpaplano tayo, pero ang Panginoon ang nagtuturo ng ating mga hakbang (Kawikaan 16:9). Kasama ni David, maipapanalangin natin, \"Ang mga panahon ko ay nasa Iyong kamay\" (Awit 31:15), alam na pinagsasama-sama ng Diyos ang lahat para sa ikabubuti ng mga umiibig sa Kanya (Roma 8:28)."
    ),
    insight: [
      t(
        "Jeremiah 29:11 is often printed on graduation cards as if it promises an easy path. But it was first spoken to people who would grow old and die in exile before the promise came true. God's plan for good included a long season in a foreign land. That should comfort every OFW: being far from home does not mean being outside God's plan. God told the exiles to build houses, plant gardens and pray for the city where they were (29:5-7). Hope is not waiting doing nothing; it is living faithfully where you are while trusting Him with what is next.",
        "Madalas nakalimbag ang Jeremias 29:11 sa mga graduation card na parang pangako ng madaling daan. Pero una itong sinabi sa mga taong tatanda at mamamatay sa pagkabihag bago matupad ang pangako. Kasama sa mabuting plano ng Diyos ang mahabang panahon sa ibang bayan. Dapat itong magbigay ng aliw sa bawat OFW: ang pagiging malayo sa bahay ay hindi nangangahulugang wala ka sa plano ng Diyos. Sinabihan ng Diyos ang mga bihag na magtayo ng bahay, magtanim at ipanalangin ang lungsod na kinaroroonan nila (t. 5-7). Ang pag-asa ay hindi paghihintay nang walang ginagawa; ito ay tapat na pamumuhay kung nasaan ka habang nagtitiwala sa Kanya para sa susunod."
      ),
      t(
        "Fear of the future often hides a desire to control. We rehearse worst-case scenarios because it makes us feel prepared. But worry does not make tomorrow safer; it only makes today heavier. Jesus gives each day its own portion of trouble and its own portion of grace. Tomorrow's grace does not arrive until tomorrow.",
        "Ang takot sa hinaharap ay madalas may nakatagong pagnanais na kontrolin ang lahat. Paulit-ulit nating iniisip ang pinakamasamang puwedeng mangyari dahil pakiramdam natin ay handa tayo. Pero hindi pinapaligtas ng pag-aalala ang bukas; pinapabigat lang nito ang ngayon. Binibigyan ni Hesus ang bawat araw ng sarili nitong bahagi ng problema at sarili nitong bahagi ng biyaya. Hindi dumarating ang biyaya ng bukas hangga't hindi pa bukas."
      ),
    ],
    life: [
      t(
        "Ramon's contract in Qatar ends in six months. He has no idea whether it will be renewed. His eldest is starting college, and the house in Batangas still has a loan. Every night he scrolls job sites until two in the morning. One Sunday a fellow OFW shared how he wrote two lists: \"My part\" (update CV, save a little, ask about renewal, pray) and \"God's part\" (the outcome). Ramon tried it. He still did his part with diligence, but he started sleeping again. His future was not clearer, but his Father was.",
        "Matatapos ang kontrata ni Ramon sa Qatar sa loob ng anim na buwan. Hindi niya alam kung ire-renew ito. Magkokolehiyo na ang panganay niya, at may utang pa ang bahay sa Batangas. Gabi-gabi, nag-i-scroll siya sa mga job site hanggang alas-dos ng madaling-araw. Isang Linggo, ikinuwento ng kapwa niya OFW kung paano siya gumawa ng dalawang listahan: \"Bahagi ko\" (i-update ang CV, mag-ipon nang kaunti, magtanong tungkol sa renewal, manalangin) at \"Bahagi ng Diyos\" (ang resulta). Sinubukan ito ni Ramon. Ginawa pa rin niya nang masipag ang bahagi niya, pero nakatulog na ulit siya. Hindi mas malinaw ang kinabukasan niya, pero mas malinaw ang Ama niya."
      ),
      t(
        "Planning is wise; God is not against insurance, savings or a five-year plan. James does not condemn planning but planning without God. \"If the Lord wills\" is not a superstitious phrase; it is a posture of a humble heart that holds plans with an open hand.",
        "Matalino ang magplano; hindi kontra ang Diyos sa insurance, ipon o limang-taong plano. Hindi pinipintasan ni Santiago ang pagpaplano kundi ang pagpaplano nang wala ang Diyos. Ang \"Kung loloobin ng Panginoon\" ay hindi pamahiin; ito ang tindig ng mapagpakumbabang puso na hawak ang mga plano nang bukas ang palad."
      ),
    ],
    twist: t(
      "We want God to show us the whole map. He usually gives us a lamp instead: \"Your word is a lamp to my feet\" (Psalm 119:105). A lamp shows the next step, not the whole road. That is not God withholding; it is God inviting you to walk with Him. If He showed you everything, you would follow the map. Because He shows you one step, you have to hold His hand.",
      "Gusto natin na ipakita ng Diyos ang buong mapa. Kadalasan, lampara ang ibinibigay Niya: \"Ang salita Mo ay ilawan sa aking mga paa\" (Awit 119:105). Ang lampara ay nagpapakita ng susunod na hakbang, hindi ng buong daan. Hindi iyon pagdadamot ng Diyos; paanyaya iyon na lumakad kang kasama Siya. Kung ipinakita Niya ang lahat, susundan mo ang mapa. Dahil isang hakbang lang ang ipinapakita Niya, kailangan mong hawakan ang kamay Niya."
    ),
    confirm: [
      t("Genesis 12:1-4: Abraham left home \"not knowing where he was going\" (Hebrews 11:8).", "Genesis 12:1-4: umalis si Abraham sa kanyang bayan \"nang hindi alam kung saan pupunta\" (Hebreo 11:8)."),
      t("Genesis 50:20: Joseph saw that what others meant for evil, God meant for good.", "Genesis 50:20: nakita ni Jose na ang balak ng iba para sa masama, binalak ng Diyos para sa mabuti."),
      t("Lamentations 3:22-23: His mercies are new every morning.", "Panaghoy 3:22-23: bago ang Kanyang mga awa tuwing umaga."),
      t("Isaiah 46:10: God declares the end from the beginning.", "Isaias 46:10: ipinahahayag ng Diyos ang wakas mula pa sa simula."),
    ],
    heart: [
      t(
        "Live in day-tight compartments: do today's duty with today's grace, and leave tomorrow in God's hand.",
        "Mamuhay nang paisa-isang araw: gawin ang tungkulin ngayon gamit ang biyaya ngayon, at iwan ang bukas sa kamay ng Diyos."
      ),
      t(
        "Hold your plans loosely and your God tightly. Make plans, then pray, \"Not my will, but Yours.\"",
        "Hawakan nang maluwag ang mga plano mo at nang mahigpit ang Diyos mo. Magplano, saka manalangin, \"Hindi ang kalooban ko, kundi ang sa Iyo.\""
      ),
    ],
    questions: [
      t("What specific \"what if\" about the future steals your peace most often?", "Anong tiyak na \"paano kung\" tungkol sa hinaharap ang pinakamadalas umagaw ng kapayapaan mo?"),
      t("Do your plans include God from the start, or do you only ask Him to bless them at the end?", "Kasama ba ang Diyos sa mga plano mo mula sa simula, o hinihingi mo lang ang basbas Niya sa dulo?"),
      t("Where are you \"in exile\" now, and how can you seek the welfare of that place?", "Saan ka \"nakabihag\" ngayon, at paano mo mahahanap ang ikabubuti ng lugar na iyon?"),
      t("What is the one next step God is lighting for you, even if the road is still dark?", "Ano ang isang susunod na hakbang na iniilawan ng Diyos para sa iyo, kahit madilim pa ang daan?"),
    ],
    actions: [
      t("Make two lists tonight: \"My part\" and \"God's part\" for the future you are worried about.", "Gumawa ng dalawang listahan ngayong gabi: \"Bahagi ko\" at \"Bahagi ng Diyos\" para sa hinaharap na ipinag-aalala mo."),
      t("Pray Psalm 31:14-15 before you sleep each night this week.", "Ipanalangin ang Awit 31:14-15 bago matulog gabi-gabi ngayong linggo."),
      t("Do one faithful thing today that \"seeks the welfare\" of your workplace or community.", "Gumawa ngayon ng isang tapat na bagay na \"humahanap ng ikabubuti\" ng trabaho o komunidad mo."),
    ],
    prayer: t(
      "Lord of my tomorrows, I confess that I have tried to carry days that have not even come. My times are in Your hand, not mine. Thank You that Your plans for me are for good and that Your mercies will be new tomorrow morning. Help me do my part faithfully and leave the outcome with You. Give me the next step and the grace to take it. In Jesus' name, Amen.",
      "Panginoon ng aking mga bukas, inaamin ko na sinubukan kong pasanin ang mga araw na hindi pa dumarating. Ang mga panahon ko ay nasa Iyong kamay, hindi sa akin. Salamat dahil ang mga plano Mo para sa akin ay para sa ikabubuti at magiging bago ang mga awa Mo bukas ng umaga. Tulungan Mo akong gawin nang tapat ang bahagi ko at iwan sa Iyo ang resulta. Ibigay Mo ang susunod na hakbang at ang biyayang gawin ito. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-anxiety-worry": {
    revelation: t(
      "Anxiety is an invitation in disguise: every worry is a burden God is asking you to hand over, because He cares for you.",
      "Ang pagkabalisa ay paanyayang nakabalatkayo: bawat alalahanin ay pasaning hinihiling ng Diyos na iabot mo sa Kanya, dahil nagmamalasakit Siya sa iyo."
    ),
    mainTruth: t(
      "\"Do not be anxious about anything, but in everything by prayer and supplication with thanksgiving let your requests be made known to God. And the peace of God, which surpasses all understanding, will guard your hearts and your minds in Christ Jesus\" (Philippians 4:6-7). Paul wrote this from prison. Peter adds, \"Humble yourselves... casting all your anxieties on Him, because He cares for you\" (1 Peter 5:6-7). Jesus points to birds and lilies: your Father knows what you need (Matthew 6:25-34). When Elijah collapsed in fear and exhaustion, God gave him sleep, food and a gentle touch before giving him a new word (1 Kings 19:3-8). And Jesus told a busy, worried Martha that \"one thing is necessary\" (Luke 10:41-42).",
      "\"Huwag kayong mabalisa sa anumang bagay, kundi sa lahat ng bagay, sa pamamagitan ng panalangin at pagsamo na may pasasalamat, ipaalam ninyo sa Diyos ang inyong mga kahilingan. At ang kapayapaan ng Diyos, na hindi kayang unawain, ang magbabantay sa inyong puso at isip kay Cristo Hesus\" (Filipos 4:6-7). Isinulat ito ni Pablo mula sa bilangguan. Dagdag ni Pedro, \"Magpakumbaba kayo... ipasa ninyo sa Kanya ang lahat ng inyong alalahanin, sapagkat nagmamalasakit Siya sa inyo\" (1 Pedro 5:6-7). Itinuro ni Hesus ang mga ibon at liryo: alam ng inyong Ama ang kailangan ninyo (Mateo 6:25-34). Nang bumagsak si Elias sa takot at pagod, binigyan siya ng Diyos ng tulog, pagkain at marahang haplos bago binigyan ng bagong salita (1 Hari 19:3-8). At sinabi ni Hesus sa abala at nag-aalalang si Marta na \"iisang bagay lang ang kailangan\" (Lucas 10:41-42)."
    ),
    insight: [
      t(
        "Notice that Peter links casting our cares with humbling ourselves. Worry can be a quiet kind of pride: \"If I do not hold this, everything will fall apart.\" Casting is an act of humility that says, \"I am not God, and I was never meant to carry this alone.\" Also notice the word \"thanksgiving\" in Philippians 4:6. Thanksgiving does not deny the problem; it remembers God's past faithfulness while facing it.",
        "Pansinin na iniuugnay ni Pedro ang pagpapasa ng alalahanin sa pagpapakumbaba. Ang pag-aalala ay puwedeng tahimik na anyo ng kayabangan: \"Kapag hindi ko ito hinawakan, babagsak ang lahat.\" Ang pagpapasa ay gawa ng kababaang-loob na nagsasabing, \"Hindi ako Diyos, at hindi ako ginawa para pasanin ito nang mag-isa.\" Pansinin din ang salitang \"pasasalamat\" sa Filipos 4:6. Hindi itinatanggi ng pasasalamat ang problema; inaalala nito ang nakaraang katapatan ng Diyos habang hinaharap ito."
      ),
      t(
        "Elijah's story shows that anxiety is not only a spiritual matter. He was exhausted, hungry and alone. God's first answer was not a sermon but a nap and a meal. Sometimes the most spiritual thing you can do is sleep, eat properly, and talk to someone. Faith and wise care go together. If anxiety is crushing you for weeks, seeing a doctor or counselor is not a lack of faith; God often heals through people.",
        "Ipinapakita ng kuwento ni Elias na ang pagkabalisa ay hindi lang usaping espirituwal. Pagod na pagod siya, gutom at nag-iisa. Ang unang sagot ng Diyos ay hindi sermon kundi tulog at pagkain. Minsan, ang pinakaespirituwal na magagawa mo ay matulog, kumain nang maayos at makipag-usap sa isang tao. Magkasama ang pananampalataya at matalinong pag-aalaga sa sarili. Kung ilang linggo ka nang dinudurog ng pagkabalisa, ang pagpapatingin sa doktor o counselor ay hindi kakulangan ng pananampalataya; madalas nagpapagaling ang Diyos sa pamamagitan ng tao."
      ),
    ],
    life: [
      t(
        "Liza is a nurse in Saudi. At night, after a twelve-hour shift, her phone lights up: her brother needs money for a hospital bill, her son failed a subject, the bank sent a reminder. Her chest tightens and her mind races until morning. A friend taught her a simple habit from Philippians 4: write each worry on a line, turn each line into a request, then add one thing she is thankful for next to it. \"Lord, my brother's bill. Thank You that You provided last time.\" The problems did not disappear in one night, but the peace that guards the heart began to stand watch over her mind.",
        "Nurse si Liza sa Saudi. Sa gabi, pagkatapos ng labindalawang oras na duty, umiilaw ang cellphone niya: kailangan ng kapatid niya ng pera para sa ospital, bumagsak sa isang subject ang anak niya, nag-text ang bangko. Sumisikip ang dibdib niya at tumatakbo ang isip niya hanggang umaga. Itinuro ng isang kaibigan ang simpleng gawi mula sa Filipos 4: isulat ang bawat alalahanin sa isang linya, gawing kahilingan ang bawat linya, at sa tabi nito, magdagdag ng isang bagay na ipinagpapasalamat niya. \"Panginoon, ang bill ng kapatid ko. Salamat dahil naglaan Ka noong nakaraan.\" Hindi nawala ang mga problema sa isang gabi, pero nagsimulang magbantay sa isip niya ang kapayapaang nagbabantay sa puso."
      ),
      t(
        "Like Martha, many of us are anxious because we are busy doing good things. Church work, family duties, side hustles: all good, but they can crowd out the \"one thing.\" Mary chose to sit at Jesus' feet. Peace is not found by finishing the list; it is found by sitting with the Lord before the list.",
        "Gaya ni Marta, marami sa atin ang balisa dahil abala sa mabubuting gawain. Gawain sa simbahan, tungkulin sa pamilya, raket: mabuti lahat, pero puwede nitong itulak palabas ang \"iisang bagay.\" Pinili ni Maria na umupo sa paanan ni Hesus. Hindi matatagpuan ang kapayapaan sa pagtatapos ng listahan; matatagpuan ito sa pag-upo kasama ng Panginoon bago ang listahan."
      ),
    ],
    twist: t(
      "Philippians 4:7 does not promise that God will explain everything; it promises a peace that \"surpasses understanding.\" We think we will have peace once we understand. God offers peace before understanding. And notice where Paul places that peace: as a soldier guarding the gate of your heart and mind. You do not have to fight off every anxious thought yourself. When you pray with thanksgiving, God posts His own guard at the door.",
      "Hindi ipinapangako ng Filipos 4:7 na ipaliliwanag ng Diyos ang lahat; ipinapangako nito ang kapayapaang \"hindi kayang unawain.\" Akala natin, magkakaroon tayo ng kapayapaan kapag naunawaan na natin. Iniaalok ng Diyos ang kapayapaan bago ang pag-unawa. At pansinin kung saan inilalagay ni Pablo ang kapayapaang iyon: parang sundalong nagbabantay sa pintuan ng puso at isip mo. Hindi mo kailangang labanan nang mag-isa ang bawat balisang isip. Kapag nanalangin ka nang may pasasalamat, ang Diyos mismo ang naglalagay ng bantay sa pinto."
    ),
    confirm: [
      t("Psalm 94:19: when anxieties multiply, God's consolations cheer the soul.", "Awit 94:19: kapag dumarami ang mga alalahanin, ang aliw ng Diyos ang nagpapasaya sa kaluluwa."),
      t("Isaiah 26:3: perfect peace for the mind that is stayed on Him.", "Isaias 26:3: lubos na kapayapaan sa isip na nakatuon sa Kanya."),
      t("Mark 4:38-39: Jesus slept in the storm, then spoke peace to the sea.", "Marcos 4:38-39: natulog si Hesus sa gitna ng bagyo, saka nagsalita ng kapayapaan sa dagat."),
      t("Psalm 4:8: \"In peace I will both lie down and sleep, for You alone make me dwell in safety.\"", "Awit 4:8: \"Payapa akong hihiga at matutulog, sapagkat Ikaw lamang ang nagpapanatili sa akin na ligtas.\""),
    ],
    heart: [
      t(
        "Turn worry into prayer the moment you notice it. Every anxious thought can become a sentence addressed to your Father.",
        "Gawing panalangin ang pag-aalala sa sandaling mapansin mo ito. Ang bawat balisang isip ay puwedeng maging pangungusap na nakatuon sa iyong Ama."
      ),
      t(
        "Practice thinking on what is true, honorable and lovely (Philippians 4:8). Guard what you feed your mind, especially late at night.",
        "Sanayin ang pag-iisip sa mga bagay na totoo, marangal at kaibig-ibig (Filipos 4:8). Bantayan ang ipinapakain mo sa isip mo, lalo na sa gabi."
      ),
    ],
    questions: [
      t("What are the top three worries on your mind right now? Have you actually prayed about each one?", "Ano ang tatlong pangunahing alalahanin mo ngayon? Talaga bang ipinanalangin mo ang bawat isa?"),
      t("Is there a way your worry is a form of trying to stay in control?", "May paraan ba na ang pag-aalala mo ay anyo ng pagsubok na manatiling may kontrol?"),
      t("Like Elijah, do you need rest, food or a friend more than you realize?", "Gaya ni Elias, kailangan mo ba ng pahinga, pagkain o kaibigan nang higit sa inaakala mo?"),
      t("What would choosing \"the one thing\" look like in your daily schedule?", "Ano ang hitsura ng pagpili sa \"iisang bagay\" sa araw-araw mong iskedyul?"),
    ],
    actions: [
      t("Write your worries tonight, turn each into a request, and add one thanksgiving beside it.", "Isulat ang mga alalahanin mo ngayong gabi, gawing kahilingan ang bawat isa, at magdagdag ng isang pasasalamat sa tabi nito."),
      t("Set a phone-free time before sleep this week and spend five minutes in Psalm 4 or Psalm 23.", "Magtakda ng oras na walang cellphone bago matulog ngayong linggo at gumugol ng limang minuto sa Awit 4 o Awit 23."),
      t("Tell one trusted person what is making you anxious, and let them pray with you.", "Sabihin sa isang taong pinagkakatiwalaan mo kung ano ang nagpapabalisa sa iyo, at hayaan siyang manalangin kasama mo."),
    ],
    prayer: t(
      "Father, my mind is crowded with worries, and I have tried to carry them alone. Right now I cast them on You, one by one, because You care for me. Thank You for every time You have provided before. Give me Your peace that I cannot explain, and let it guard my heart and mind. Teach me to rest, to sit at Your feet, and to trust You with what I cannot control. In Jesus' name, Amen.",
      "Ama, punong-puno ng alalahanin ang isip ko, at sinubukan kong pasanin ang mga ito nang mag-isa. Ngayon, ipinapasa ko ang mga ito sa Iyo, isa-isa, dahil nagmamalasakit Ka sa akin. Salamat sa bawat pagkakataong naglaan Ka noon. Bigyan Mo ako ng kapayapaan Mo na hindi ko maipaliwanag, at hayaang bantayan nito ang puso at isip ko. Turuan Mo akong magpahinga, umupo sa paanan Mo, at magtiwala sa Iyo sa mga bagay na hindi ko kontrolado. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-trauma-healing": {
    revelation: t(
      "God does not stand far from your deepest wound; He comes closest exactly where you are most broken.",
      "Hindi lumalayo ang Diyos sa pinakamalalim mong sugat; pinakamalapit Siya mismo kung saan ka pinakawasak."
    ),
    mainTruth: t(
      "\"The Lord is near to the brokenhearted and saves the crushed in spirit\" (Psalm 34:18). \"He heals the brokenhearted and binds up their wounds\" (Psalm 147:3). Jesus applied Isaiah 61 to Himself: He was sent \"to bind up the brokenhearted... to give them a beautiful headdress instead of ashes\" (Isaiah 61:1-3; Luke 4:18-21). Psalm 13 shows that a believer can cry, \"How long, O Lord?\" and still end with trust. Joseph, betrayed and enslaved by his brothers, later said, \"You meant evil against me, but God meant it for good\" (Genesis 50:20). And God comforts us in our affliction \"so that we may be able to comfort those who are in any affliction\" (2 Corinthians 1:3-4).",
      "\"Malapit ang Panginoon sa mga wasak ang puso at inililigtas Niya ang mga durog ang espiritu\" (Awit 34:18). \"Pinagagaling Niya ang mga wasak ang puso at tinatalian ang kanilang mga sugat\" (Awit 147:3). Inilapat ni Hesus sa Kanyang sarili ang Isaias 61: isinugo Siya \"upang talian ang mga wasak ang puso... upang bigyan sila ng magandang korona kapalit ng abo\" (Isaias 61:1-3; Lucas 4:18-21). Ipinapakita ng Awit 13 na ang mananampalataya ay puwedeng sumigaw ng, \"Hanggang kailan, Panginoon?\" at magtapos pa rin sa pagtitiwala. Si Jose, na ipinagkanulo at ipinagbili ng mga kapatid, ay kalaunang nagsabi, \"Binalak ninyo ang masama laban sa akin, pero binalak ito ng Diyos para sa mabuti\" (Genesis 50:20). At inaaliw tayo ng Diyos sa ating kapighatian \"upang maaliw rin natin ang mga nasa anumang kapighatian\" (2 Corinto 1:3-4)."
    ),
    insight: [
      t(
        "Many Christians think a strong believer should \"move on\" quickly. Scripture is more honest. David wrote psalms of lament. Jesus wept at Lazarus' tomb. Joseph wept loudly when he saw his brothers, years after the betrayal (Genesis 45:2). Healing is not pretending it did not hurt. God binds wounds; He does not ask you to deny you have them. Some of the deepest worship in the Bible is spoken through tears.",
        "Maraming Kristiyano ang nag-aakala na ang matatag na mananampalataya ay dapat mabilis na \"maka-move on.\" Mas tapat ang Kasulatan. Sumulat si David ng mga awit ng pagtangis. Umiyak si Hesus sa libingan ni Lazaro. Humagulgol si Jose nang makita ang mga kapatid niya, ilang taon matapos ang pagtataksil (Genesis 45:2). Ang paggaling ay hindi pagkukunwaring hindi ito masakit. Tinatalian ng Diyos ang sugat; hindi Niya hinihiling na itanggi mong mayroon ka nito. May ilan sa pinakamalalim na pagsamba sa Bibliya na binigkas sa gitna ng luha."
      ),
      t(
        "Joseph's healing also took time: years in Egypt, two sons he named \"God made me forget my hardship\" and \"God made me fruitful in the land of my affliction\" (Genesis 41:51-52). Forgiving his brothers did not mean pretending they were safe; he tested them first. Healing from trauma may involve wise boundaries, honest conversations and sometimes professional help. God can use all of these.",
        "Natagalan din ang paggaling ni Jose: ilang taon sa Ehipto, dalawang anak na pinangalanan niyang \"Ipinalimot sa akin ng Diyos ang aking hirap\" at \"Pinagbunga ako ng Diyos sa lupain ng aking kapighatian\" (Genesis 41:51-52). Ang pagpapatawad sa mga kapatid ay hindi nangahulugang nagkunwari siyang ligtas na sila; sinubok muna niya sila. Ang paggaling mula sa trauma ay maaaring may kasamang matalinong hangganan, tapat na pag-uusap at minsan ay tulong ng propesyonal. Kayang gamitin ng Diyos ang lahat ng ito."
      ),
    ],
    life: [
      t(
        "Rhea survived an abusive employer in her first contract abroad. She came home, found work in Manila, and joined a church. On the outside she was fine. Inside, a raised voice could make her freeze, and she never told anyone why. One day in a small group, someone read Psalm 34:18 and said, \"God is not afraid of your story.\" For the first time, Rhea spoke about what happened. The group did not fix her; they wept with her, prayed for her, and helped her find a Christian counselor. A year later she started helping returning OFWs at her church. Her wound became a place of comfort for others, just as 2 Corinthians 1:4 says.",
        "Nakaligtas si Rhea sa isang mapang-abusong amo sa una niyang kontrata sa abroad. Umuwi siya, nakahanap ng trabaho sa Maynila, at sumali sa isang simbahan. Sa labas, mukhang ayos siya. Sa loob, ang isang malakas na boses ay kayang magpatigil sa kanya, at hindi niya sinabi kahit kanino kung bakit. Isang araw sa small group, may bumasa ng Awit 34:18 at nagsabi, \"Hindi natatakot ang Diyos sa kuwento mo.\" Sa unang pagkakataon, ikinuwento ni Rhea ang nangyari. Hindi siya inayos ng grupo; umiyak sila kasama niya, ipinanalangin siya, at tinulungan siyang makahanap ng Kristiyanong counselor. Makalipas ang isang taon, nagsimula siyang tumulong sa mga umuuwing OFW sa simbahan nila. Ang sugat niya ay naging lugar ng aliw para sa iba, gaya ng sinasabi ng 2 Corinto 1:4."
      ),
      t(
        "Trauma comes in many forms: a violent home, a sudden death, a disaster like a typhoon or earthquake, abuse, betrayal. You may carry it in your body, sleep and relationships. The good news is not that you will forget everything, but that the scars can stop controlling you. Jesus rose with scars, yet those scars became proof of victory, not signs of defeat.",
        "Maraming anyo ang trauma: marahas na tahanan, biglaang pagkamatay, sakuna gaya ng bagyo o lindol, pang-aabuso, pagtataksil. Maaaring dala mo ito sa katawan, sa tulog at sa mga relasyon mo. Ang mabuting balita ay hindi na makakalimutan mo ang lahat, kundi maaaring tumigil ang mga peklat sa pagkontrol sa iyo. Bumangon si Hesus nang may mga peklat, pero ang mga peklat na iyon ay naging patunay ng tagumpay, hindi tanda ng pagkatalo."
      ),
    ],
    twist: t(
      "We expect God to remove the pain and then use us. Often He uses us through the healed places, not around them. The risen Jesus did not hide His wounds; He showed them to Thomas, and Thomas believed (John 20:27-28). Your healed scar may be the very thing that helps another wounded person believe that God is real. In God's hands, a scar is not a defect; it is a testimony.",
      "Inaasahan natin na aalisin muna ng Diyos ang sakit bago tayo gamitin. Madalas, ginagamit Niya tayo sa pamamagitan ng mga lugar na pinagaling, hindi sa paligid ng mga ito. Hindi itinago ng muling nabuhay na Hesus ang Kanyang mga sugat; ipinakita Niya ito kay Tomas, at naniwala si Tomas (Juan 20:27-28). Ang gumaling mong peklat ay maaaring siyang tutulong sa isa pang sugatang tao na maniwalang totoo ang Diyos. Sa kamay ng Diyos, ang peklat ay hindi depekto; ito ay patotoo."
    ),
    confirm: [
      t("Psalm 13:1-6: David moves from \"How long?\" to \"I have trusted in Your steadfast love.\"", "Awit 13:1-6: mula sa \"Hanggang kailan?\" ay umabot si David sa \"Nagtiwala ako sa Iyong walang-hanggang pag-ibig.\""),
      t("Genesis 16:13: abused and alone, Hagar met \"the God who sees me.\"", "Genesis 16:13: inabuso at nag-iisa, nakilala ni Hagar ang \"Diyos na nakakakita sa akin.\""),
      t("Luke 8:43-48: Jesus healed the woman's body and then restored her dignity in public.", "Lucas 8:43-48: pinagaling ni Hesus ang katawan ng babae at pagkatapos ay ibinalik ang dangal niya sa harap ng lahat."),
      t("Revelation 21:4: one day God will wipe away every tear.", "Pahayag 21:4: balang araw, papahirin ng Diyos ang bawat luha."),
    ],
    heart: [
      t(
        "Give yourself permission to grieve honestly before God. Lament is not unbelief; it is faith that still talks to God in the dark.",
        "Bigyan ang sarili ng pahintulot na magdalamhati nang tapat sa harap ng Diyos. Ang pagtangis ay hindi kawalan ng pananampalataya; ito ay pananampalatayang patuloy na nakikipag-usap sa Diyos sa dilim."
      ),
      t(
        "Let God, and safe people, into the locked rooms of your heart. Healing grows in honest, patient community.",
        "Papasukin ang Diyos, at ang mga taong ligtas, sa mga nakakandadong silid ng puso mo. Lumalago ang paggaling sa tapat at matiyagang samahan."
      ),
    ],
    questions: [
      t("Is there a painful memory you have never told God about honestly?", "May masakit bang alaala na hindi mo pa naikukuwento nang tapat sa Diyos?"),
      t("How does that wound still show up in your reactions, sleep or relationships?", "Paano pa rin lumilitaw ang sugat na iyon sa mga reaksyon, tulog o relasyon mo?"),
      t("Who is one safe person you could share your story with, and when?", "Sino ang isang ligtas na taong mapagbabahagian mo ng kuwento mo, at kailan?"),
      t("How might God use your healing to comfort someone else one day?", "Paano maaaring gamitin ng Diyos ang paggaling mo para aliwin ang iba balang araw?"),
    ],
    actions: [
      t("Write your own Psalm 13: start with \"How long, Lord?\" and end with one line of trust.", "Isulat ang sarili mong Awit 13: magsimula sa \"Hanggang kailan, Panginoon?\" at magtapos sa isang linya ng pagtitiwala."),
      t("Talk to a pastor, mature believer or Christian counselor about one wound this week.", "Kausapin ang isang pastor, matatag na mananampalataya o Kristiyanong counselor tungkol sa isang sugat ngayong linggo."),
      t("Read Psalm 34:18 slowly every morning and thank God that He is near.", "Basahin nang dahan-dahan ang Awit 34:18 tuwing umaga at pasalamatan ang Diyos na malapit Siya."),
    ],
    prayer: t(
      "Lord, You are near to the brokenhearted, and today I come to You with the broken parts I usually hide. You saw what happened. You know how it still affects me. I do not have to pretend before You. Bind up my wounds, Jesus. Give me beauty for ashes and gladness for mourning. Lead me to safe people who can walk with me, and one day use my scars to comfort others. In Your name, Amen.",
      "Panginoon, malapit Ka sa mga wasak ang puso, at ngayon lumalapit ako sa Iyo dala ang mga basag na bahaging karaniwan kong itinatago. Nakita Mo ang nangyari. Alam Mo kung paano pa rin ito nakakaapekto sa akin. Hindi ko kailangang magkunwari sa harap Mo. Talian Mo ang mga sugat ko, Hesus. Bigyan Mo ako ng ganda kapalit ng abo at ng saya kapalit ng pagdadalamhati. Akayin Mo ako sa mga taong ligtas na sasamahan ako, at balang araw gamitin Mo ang mga peklat ko para aliwin ang iba. Sa Iyong pangalan, Amen."
    ),
  },

  "c-promises-for-fear": {
    revelation: t(
      "The answer to fear is not a feeling of courage but a Person who keeps His word: \"Fear not, for I am with you.\"",
      "Ang sagot sa takot ay hindi pakiramdam ng tapang kundi isang Persona na tumutupad ng salita Niya: \"Huwag kang matakot, sapagkat Ako ay kasama mo.\""
    ),
    mainTruth: t(
      "\"Fear not, for I am with you; be not dismayed, for I am your God; I will strengthen you, I will help you, I will uphold you with My righteous right hand\" (Isaiah 41:10). \"When you pass through the waters, I will be with you\" (Isaiah 43:2): not if, but when. God told Joshua, \"Be strong and courageous... for the Lord your God is with you wherever you go\" (Joshua 1:9). David walked through the valley of the shadow of death and feared no evil, \"for You are with me\" (Psalm 23:4). \"I will never leave you nor forsake you\" (Hebrews 13:5). And \"all the promises of God find their Yes in Him,\" in Jesus (2 Corinthians 1:20).",
      "\"Huwag kang matakot, sapagkat Ako ay kasama mo; huwag kang manlupaypay, sapagkat Ako ang iyong Diyos; palalakasin kita, tutulungan kita, aalalayan kita ng Aking matuwid na kanang kamay\" (Isaias 41:10). \"Kapag dumaan ka sa tubig, Ako ay sasaiyo\" (Isaias 43:2): hindi kung, kundi kapag. Sinabi ng Diyos kay Josue, \"Magpakalakas ka at magpakatapang... sapagkat ang Panginoon mong Diyos ay kasama mo saan ka man pumunta\" (Josue 1:9). Lumakad si David sa libis ng lilim ng kamatayan at hindi natakot sa anumang masama, \"sapagkat Ikaw ay kasama ko\" (Awit 23:4). \"Hindi kita iiwan ni pababayaan man\" (Hebreo 13:5). At \"ang lahat ng pangako ng Diyos ay \"Oo\" kay Cristo\" (2 Corinto 1:20)."
    ),
    insight: [
      t(
        "Look at the reason God gives in almost every \"fear not\": \"for I am with you.\" He rarely says \"fear not, because nothing bad will happen.\" He says \"fear not, because I will be there when it happens.\" The promise is not the absence of waters and fire but the presence of God in them. Many believers are disappointed with God because they read His promises as guarantees of comfort instead of guarantees of company.",
        "Tingnan ang dahilang ibinibigay ng Diyos sa halos bawat \"huwag kang matakot\": \"sapagkat Ako ay kasama mo.\" Bihira Niyang sabihing \"huwag kang matakot, dahil walang masamang mangyayari.\" Ang sinasabi Niya ay \"huwag kang matakot, dahil naroon Ako kapag nangyari ito.\" Ang pangako ay hindi kawalan ng tubig at apoy kundi presensya ng Diyos sa gitna ng mga ito. Maraming mananampalataya ang nabibigo sa Diyos dahil binabasa nila ang mga pangako Niya bilang garantiya ng ginhawa sa halip na garantiya ng pagsama."
      ),
      t(
        "Promises are only as strong as the one who makes them. Isaiah 43:1 grounds the promise in God's past acts: \"I have redeemed you; I have called you by name, you are Mine.\" Before He says what He will do, He reminds you who you are to Him. Fear says, \"Look at the size of the problem.\" Faith says, \"Look at the faithfulness of the One who promised.\"",
        "Ang lakas ng pangako ay nakadepende sa nangangako. Itinayo ng Isaias 43:1 ang pangako sa mga nagawa na ng Diyos: \"Tinubos kita; tinawag kita sa pangalan mo, ikaw ay Akin.\" Bago Niya sabihin ang gagawin Niya, ipinapaalala Niya kung sino ka sa Kanya. Sabi ng takot, \"Tingnan mo ang laki ng problema.\" Sabi ng pananampalataya, \"Tingnan mo ang katapatan ng Nangako.\""
      ),
    ],
    life: [
      t(
        "During a strong typhoon, a mother in Samar huddled with her three children in the dark as the wind tore at the roof. She could not stop the storm, so she did the only thing she knew. She held them close and kept repeating Isaiah 41:10, line by line, and the children began repeating it with her. In the morning the house was damaged, but they were alive. Years later her eldest, now a pastor, said, \"I do not remember the wind as much as I remember my mother's voice saying, 'I am with you.'\" That is what God's promises do: they become a voice louder than the storm.",
        "Sa isang malakas na bagyo, nagsiksikan sa dilim ang isang nanay sa Samar at ang tatlo niyang anak habang pinupunit ng hangin ang bubong. Hindi niya mapigilan ang bagyo, kaya ginawa niya ang tanging alam niya. Niyakap niya sila nang mahigpit at paulit-ulit na binigkas ang Isaias 41:10, linya por linya, at nagsimulang sumabay ang mga bata. Kinaumagahan, sira ang bahay, pero buhay sila. Makalipas ang maraming taon, sabi ng panganay niya, na pastor na ngayon, \"Hindi ko masyadong naaalala ang hangin; mas naaalala ko ang boses ng nanay ko na nagsasabing, 'Ako ay kasama mo.'\" Iyan ang ginagawa ng mga pangako ng Diyos: nagiging tinig itong mas malakas kaysa sa bagyo."
      ),
      t(
        "You may be facing a medical test, a court case, a visa decision or an empty bank account. Fear wants you to rehearse the problem. God invites you to rehearse His promises. Keep them on your phone lock screen, in your wallet, on the wall of your bunk bed. A promise remembered is a weapon in your hand.",
        "Maaaring humaharap ka sa medical test, kaso sa korte, desisyon sa visa o walang-lamang bank account. Gusto ng takot na paulit-ulit mong isipin ang problema. Inaanyayahan ka ng Diyos na paulit-ulit na alalahanin ang mga pangako Niya. Ilagay ang mga ito sa lock screen ng cellphone mo, sa pitaka mo, sa dingding ng double-deck mo. Ang pangakong naaalala ay sandata sa kamay mo."
      ),
    ],
    twist: t(
      "We think we need more faith to claim God's promises. But 2 Corinthians 1:20 says every promise is already \"Yes\" in Jesus. You are not trying to convince God to keep His word; He has already said yes in His Son. Your part is the \"Amen\": agreeing with what He has already said. Fear asks, \"Will God come through?\" The cross answers, \"He already did, and He did not spare even His own Son\" (Romans 8:32).",
      "Akala natin, kailangan natin ng mas malaking pananampalataya para angkinin ang mga pangako ng Diyos. Pero sabi ng 2 Corinto 1:20, ang bawat pangako ay \"Oo\" na kay Hesus. Hindi mo kinukumbinsi ang Diyos na tuparin ang salita Niya; nag-\"Oo\" na Siya sa pamamagitan ng Kanyang Anak. Ang bahagi mo ay ang \"Amen\": ang pagsang-ayon sa sinabi na Niya. Tanong ng takot, \"Darating ba ang tulong ng Diyos?\" Sagot ng krus, \"Dumating na, at hindi Niya ipinagkait kahit ang sarili Niyang Anak\" (Roma 8:32)."
    ),
    confirm: [
      t("Daniel 3:25: in the fire there was a fourth Man walking with the three.", "Daniel 3:25: sa apoy ay may ikaapat na Lalaking lumalakad kasama ng tatlo."),
      t("Matthew 28:20: \"I am with you always, to the end of the age.\"", "Mateo 28:20: \"Ako ay kasama ninyo palagi, hanggang sa katapusan ng panahon.\""),
      t("Numbers 23:19: God is not a man that He should lie.", "Bilang 23:19: ang Diyos ay hindi tao na magsisinungaling."),
      t("Psalm 56:3: \"When I am afraid, I put my trust in You.\"", "Awit 56:3: \"Kapag ako ay natatakot, nagtitiwala ako sa Iyo.\""),
    ],
    heart: [
      t(
        "Fill your mind with God's promises before fear fills it with its own predictions. What you meditate on will shape what you expect.",
        "Punuin ang isip mo ng mga pangako ng Diyos bago ito punuin ng takot ng sarili nitong mga hula. Ang binubulay-bulay mo ang huhubog sa inaasahan mo."
      ),
      t(
        "Become a promise-speaker for others. Like that mother in the storm, your calm voice can carry God's word into someone else's fear.",
        "Maging tagapagsalita ng pangako para sa iba. Gaya ng nanay sa bagyo, ang mahinahong tinig mo ay puwedeng maghatid ng salita ng Diyos sa takot ng iba."
      ),
    ],
    questions: [
      t("Have you read God's promises as guarantees of comfort or as guarantees of His presence?", "Binasa mo ba ang mga pangako ng Diyos bilang garantiya ng ginhawa o garantiya ng Kanyang presensya?"),
      t("Which \"waters\" or \"fire\" are you walking through right now?", "Anong \"tubig\" o \"apoy\" ang dinaraanan mo ngayon?"),
      t("Which promise of God do you most need to believe this week?", "Aling pangako ng Diyos ang pinakakailangan mong paniwalaan ngayong linggo?"),
      t("Who around you is afraid and needs to hear God's promise from you?", "Sino sa paligid mo ang natatakot at kailangang marinig mula sa iyo ang pangako ng Diyos?"),
    ],
    actions: [
      t("Choose one promise from this lesson, memorize it, and put it on your lock screen.", "Pumili ng isang pangako mula sa araling ito, isaulo ito, at ilagay sa lock screen mo."),
      t("Each time fear rises this week, speak that promise out loud and add, \"Amen, Lord.\"", "Tuwing umaangat ang takot ngayong linggo, bigkasin nang malakas ang pangakong iyon at idagdag, \"Amen, Panginoon.\""),
      t("Send one promise verse to a friend or family member who is going through a hard time.", "Magpadala ng isang talatang pangako sa isang kaibigan o kapamilyang dumaraan sa mahirap na panahon."),
    ],
    prayer: t(
      "Faithful God, You have said, \"Fear not, for I am with you,\" and I choose to believe You. You have redeemed me and called me by name; I am Yours. When I pass through the waters, be with me. When I walk through the fire, hold my hand. Thank You that all Your promises are Yes in Jesus. I say Amen to Your word today, and I rest in Your presence. In Jesus' name, Amen.",
      "Tapat na Diyos, sinabi Mo, \"Huwag kang matakot, sapagkat Ako ay kasama mo,\" at pinipili kong paniwalaan Ka. Tinubos Mo ako at tinawag sa pangalan ko; ako ay Iyo. Kapag dumaan ako sa tubig, samahan Mo ako. Kapag lumakad ako sa apoy, hawakan Mo ang kamay ko. Salamat dahil ang lahat ng pangako Mo ay Oo kay Hesus. Nag-a-Amen ako sa salita Mo ngayon, at nagpapahinga ako sa presensya Mo. Sa pangalan ni Hesus, Amen."
    ),
  },

  "c-living-by-faith": {
    revelation: t(
      "Faith is not a feeling you wait for; it is a step you take because God has spoken, even before you can see.",
      "Ang pananampalataya ay hindi pakiramdam na hinihintay mo; ito ay hakbang na ginagawa mo dahil nagsalita ang Diyos, kahit hindi mo pa nakikita."
    ),
    mainTruth: t(
      "\"Faith is the assurance of things hoped for, the conviction of things not seen... Without faith it is impossible to please Him, for whoever would draw near to God must believe that He exists and that He rewards those who seek Him\" (Hebrews 11:1, 6). Abraham obeyed and went out, \"not knowing where he was going\" (Hebrews 11:8). \"We walk by faith, not by sight\" (2 Corinthians 5:7). Faith comes from hearing the word of Christ (Romans 10:17). In the storm, Jesus asked His disciples, \"Why are you so afraid? Have you still no faith?\" (Mark 4:40). And a desperate father cried, \"I believe; help my unbelief!\" and Jesus healed his son (Mark 9:24).",
      "\"Ang pananampalataya ay katiyakan sa mga bagay na inaasahan, katunayan ng mga bagay na hindi nakikita... Kung walang pananampalataya, imposibleng mapalugdan Siya, sapagkat ang lumalapit sa Diyos ay dapat maniwala na Siya ay buhay at ginagantimpalaan Niya ang mga humahanap sa Kanya\" (Hebreo 11:1, 6). Sumunod si Abraham at umalis, \"nang hindi alam kung saan pupunta\" (Hebreo 11:8). \"Lumalakad tayo sa pananampalataya, hindi sa nakikita\" (2 Corinto 5:7). Ang pananampalataya ay nagmumula sa pakikinig sa salita ni Cristo (Roma 10:17). Sa bagyo, tinanong ni Hesus ang mga alagad, \"Bakit kayo takot na takot? Wala pa ba kayong pananampalataya?\" (Marcos 4:40). At sumigaw ang isang desperadong ama, \"Naniniwala ako; tulungan Mo ang aking kawalan ng pananampalataya!\" at pinagaling ni Hesus ang anak niya (Marcos 9:24)."
    ),
    insight: [
      t(
        "The father in Mark 9 gives hope to every struggling believer. His faith was mixed with doubt, and he admitted it. Jesus did not reject him for having imperfect faith; He answered the little faith that was there. Faith is not the absence of doubt; it is bringing your doubt to Jesus instead of running away from Him. What matters most is not the size of your faith but the size of the One you trust.",
        "Ang ama sa Marcos 9 ay nagbibigay ng pag-asa sa bawat nahihirapang mananampalataya. May halong pagdududa ang pananampalataya niya, at inamin niya ito. Hindi siya tinanggihan ni Hesus dahil hindi perpekto ang pananampalataya niya; sinagot Niya ang maliit na pananampalatayang naroon. Ang pananampalataya ay hindi kawalan ng pagdududa; ito ay pagdadala ng pagdududa mo kay Hesus sa halip na lumayo sa Kanya. Ang pinakamahalaga ay hindi ang laki ng pananampalataya mo kundi ang laki ng Pinagtitiwalaan mo."
      ),
      t(
        "Notice that in the storm, the disciples did pray: \"Teacher, do You not care that we are perishing?\" Their problem was not that they called on Jesus but that they doubted His care while He was right there in the boat. Unbelief often sounds like \"God, do You even care?\" Faith remembers that if Jesus is in your boat, the boat is not going down without Him.",
        "Pansinin na sa bagyo, nanalangin naman ang mga alagad: \"Guro, wala Ka bang pakialam na mamamatay na kami?\" Hindi ang pagtawag nila kay Hesus ang problema kundi ang pagdududa nila sa malasakit Niya habang naroon Siya mismo sa bangka. Ang kawalan ng pananampalataya ay madalas tunog \"Diyos, may pakialam Ka ba?\" Naaalala ng pananampalataya na kung nasa bangka mo si Hesus, hindi lulubog ang bangka nang wala Siya."
      ),
    ],
    life: [
      t(
        "Faith in daily life is often quiet and unglamorous. It is a tricycle driver who refuses to cheat on fares because he trusts God to provide. It is a young couple tithing on a tight salary. It is an OFW who says no to a lucrative but dishonest offer. It is a mother who keeps praying for her prodigal son for ten years. None of them can see the result yet. All of them are walking by faith.",
        "Ang pananampalataya sa araw-araw ay madalas tahimik at hindi kapansin-pansin. Ito ang tricycle driver na ayaw mandaya sa pamasahe dahil nagtitiwala siya na maglalaan ang Diyos. Ito ang batang mag-asawang nag-iikapu kahit maliit ang sahod. Ito ang OFW na tumatanggi sa malaking pero hindi tapat na alok. Ito ang inang patuloy na nananalangin para sa naliligaw niyang anak sa loob ng sampung taon. Wala pa sa kanila ang nakakakita ng resulta. Lahat sila ay lumalakad sa pananampalataya."
      ),
      t(
        "Jun had saved for years to put up a small hardware store, but he felt God leading him to first finish paying an old debt to a former employer he had wronged. It made no sense on paper. He obeyed, paid it all, and started over from a smaller amount. The store opened two years later than planned. Today he says, \"The delay was where God built my faith. Now I know my store is not built on my cleverness but on His word.\"",
        "Ilang taon nag-ipon si Jun para magtayo ng maliit na hardware, pero naramdaman niyang inaakay siya ng Diyos na unahing bayaran ang lumang utang sa dating amo na nagawan niya ng mali. Hindi ito makatwiran sa papel. Sumunod siya, binayaran lahat, at nagsimula muli sa mas maliit na halaga. Dalawang taong naantala ang pagbubukas ng tindahan. Ngayon, sabi niya, \"Sa pagkaantala itinayo ng Diyos ang pananampalataya ko. Alam ko na ngayon na ang tindahan ko ay hindi nakatayo sa talino ko kundi sa salita Niya.\""
      ),
    ],
    twist: t(
      "Hebrews 11 ends in a surprising way: many of these heroes of faith \"died in faith, not having received the things promised\" (Hebrews 11:13, 39). Faith is not a tool to get what we want quickly. It is a way of living that trusts God so deeply that even if the answer comes after we die, we know He is faithful. The world says, \"Seeing is believing.\" The Kingdom says, \"Believing is seeing,\" and sometimes the seeing happens in eternity.",
      "Nakakagulat ang pagtatapos ng Hebreo 11: marami sa mga bayani ng pananampalataya ay \"namatay sa pananampalataya nang hindi natatanggap ang mga ipinangako\" (Hebreo 11:13, 39). Ang pananampalataya ay hindi kasangkapan para makuha agad ang gusto natin. Ito ay paraan ng pamumuhay na lubos na nagtitiwala sa Diyos, kaya kahit dumating ang sagot pagkamatay natin, alam nating tapat Siya. Sabi ng mundo, \"Makita muna bago maniwala.\" Sabi ng Kaharian, \"Maniwala, at makikita mo,\" at minsan ang pagkakita ay mangyayari sa walang-hanggan."
    ),
    confirm: [
      t("Genesis 22:8: Abraham said, \"God will provide for Himself the lamb.\"", "Genesis 22:8: sabi ni Abraham, \"Ang Diyos ang maglalaan ng tupa.\""),
      t("Matthew 14:28-31: Peter walked on water while his eyes were on Jesus.", "Mateo 14:28-31: lumakad si Pedro sa tubig habang nakatuon ang mata niya kay Hesus."),
      t("Habakkuk 2:4: \"The righteous shall live by his faith.\"", "Habakuk 2:4: \"Ang matuwid ay mabubuhay sa pananampalataya.\""),
      t("Luke 17:5-6: faith as small as a mustard seed can move what seems immovable.", "Lucas 17:5-6: ang pananampalatayang kasinliit ng buto ng mustasa ay kayang magpagalaw ng tila hindi matinag."),
    ],
    heart: [
      t(
        "Feed your faith with God's word daily, because faith grows by hearing. A starved faith will always be a fearful faith.",
        "Pakainin araw-araw ang pananampalataya mo ng salita ng Diyos, dahil lumalago ito sa pakikinig. Ang pananampalatayang gutom ay laging takot."
      ),
      t(
        "Move from waiting to feel ready to obeying while you still feel weak. Courage usually follows the first step, not before it.",
        "Lumipat mula sa paghihintay na maramdamang handa ka tungo sa pagsunod kahit mahina pa ang pakiramdam mo. Kadalasan, sumusunod ang tapang sa unang hakbang, hindi nauuna rito."
      ),
    ],
    questions: [
      t("Where is God asking you to step out before you can see the full picture?", "Saan ka hinihiling ng Diyos na humakbang bago mo pa makita ang buong larawan?"),
      t("Is your faith mixed with doubt? Have you brought that doubt honestly to Jesus?", "May halong pagdududa ba ang pananampalataya mo? Dinala mo ba nang tapat ang pagdududang iyon kay Hesus?"),
      t("In your current storm, do you doubt God's power, or His care?", "Sa bagyo mo ngayon, ang pinagdududahan mo ba ay ang kapangyarihan ng Diyos, o ang malasakit Niya?"),
      t("How much of God's word are you hearing each day to feed your faith?", "Gaano karaming salita ng Diyos ang naririnig mo araw-araw para pakainin ang pananampalataya mo?"),
    ],
    actions: [
      t("Pray the honest prayer of Mark 9:24 about one situation where you struggle to believe.", "Ipanalangin ang tapat na panalangin ng Marcos 9:24 tungkol sa isang sitwasyon kung saan nahihirapan kang maniwala."),
      t("Take one concrete step of obedience this week that you have been postponing.", "Gumawa ngayong linggo ng isang tiyak na hakbang ng pagsunod na matagal mo nang ipinagpapaliban."),
      t("Read one chapter of a Gospel each day this week, listening for one word to trust.", "Magbasa ng isang kabanata ng Ebanghelyo araw-araw ngayong linggo, at makinig sa isang salitang pagtitiwalaan."),
    ],
    prayer: t(
      "Lord Jesus, I believe; help my unbelief. You know how often I want to see before I trust. Thank You that You are in my boat, even when the waves are high. Grow my faith by Your word. Give me courage to take the next step You show me, even when I cannot see the end. Let my life please You, not by being perfect, but by trusting You fully. In Your name, Amen.",
      "Panginoong Hesus, naniniwala ako; tulungan Mo ang aking kawalan ng pananampalataya. Alam Mo kung gaano kadalas kong gustong makita muna bago magtiwala. Salamat dahil nasa bangka Kita, kahit malalaki ang alon. Palaguin Mo ang pananampalataya ko sa pamamagitan ng salita Mo. Bigyan Mo ako ng tapang na gawin ang susunod na hakbang na ipinapakita Mo, kahit hindi ko pa nakikita ang dulo. Mapalugdan Ka nawa ng buhay ko, hindi sa pagiging perpekto, kundi sa lubos na pagtitiwala sa Iyo. Sa Iyong pangalan, Amen."
    ),
  },
};
